triggers.def:
try {

    var contract = api.get('/api/v1/contract/$self')
    var usage = api.get('/api/v1/metrics/activity?object=services&interval=period&period=1&subAccounts=true')

    if (usage.status == 200 && contract.status == 200) {

        //log.trace('contract', contract)

        var limit = contract.body.eventsPerDay
        var today = usage.body['series']['*'][0].count

        var pct = Math.trunc((today * 100) / limit)

        if (pct >= (+global.values.eventUsageAlertConfig.percentUsage)) {
            var mail = {
                to: global.values.eventUsageAlertConfig.sendTo,
                subject: 'IOTB Usage Alert',
                title: 'IOTB Usage Alert',
                message: 'Your Tartabit IoT Bridge usage is {{.Params.Pct}}%  You used Math.trunc({{.Params.Current}})K/{{.Params.Limit}}K events in the past day.',
                params: {
                    Pct: pct,
                    Current: today/1000,
                    Limit: limit/1000,
                },
            }

            email.send(mail)
        }
    } else {
        log.warn('could not query usage or limit', {usage: usage, limit: limit})
    }

} catch (e) {
    log.warn('could not query usage or limit', e)
}
